CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_listar_evaluaciones_seccion`(
    IN p_id_seccion INT
)
BEGIN
    SELECT 
        MIN(c.id_calificacion) AS id_evaluacion,
        c.nombre_evaluacion AS nombre,
        MAX(c.ponderado) AS ponderado,
        DATE(MIN(c.fecha_registro)) AS fecha_evaluacion
    FROM calificacion c
    INNER JOIN detalle_matricula dm 
        ON c.id_detalle_matricula = dm.id_detalle_matricula
    WHERE dm.id_seccion = p_id_seccion
    GROUP BY c.nombre_evaluacion
    ORDER BY fecha_evaluacion ASC, id_evaluacion ASC;
END ;;
