CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_registrar_calificacion`(
    IN p_id_detalle_matricula INT,
    IN p_id_evaluacion INT,
    IN p_nota DECIMAL(4,2)
)
BEGIN
    DECLARE v_nombre_eval VARCHAR(50);
    DECLARE v_ponderado DECIMAL(5,2);

    -- Busca nombre y ponderado de referencia (por ejemplo desde calificacion o una tabla evaluacion)
    SELECT 
        nombre_evaluacion,
        CASE WHEN ponderado > 1 THEN ponderado / 100 ELSE ponderado END
    INTO v_nombre_eval, v_ponderado
    FROM calificacion
    WHERE id_calificacion = p_id_evaluacion
    LIMIT 1;

    -- Valores de respaldo si aún no existe esa evaluación de referencia
    SET v_nombre_eval = IFNULL(v_nombre_eval, CONCAT('EVAL-', p_id_evaluacion));
    SET v_ponderado = IFNULL(v_ponderado, 0.20);

    INSERT INTO calificacion (
        id_detalle_matricula,
        nombre_evaluacion,
        ponderado,
        nota
    )
    VALUES (
        p_id_detalle_matricula,
        v_nombre_eval,
        v_ponderado,
        p_nota
    );
END ;;
DELIMITER ;
