DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ver_alumnos_seccion`(
    IN p_id_periodo INT -- Opcional: pasa un id_periodo o NULL para ver todos los periodos
)
BEGIN
    SELECT 
        pa.nombre AS periodo,
        s.id_seccion,
        s.codigo_seccion,
        c.codigo AS codigo_curso,
        c.nombre AS curso,
        s.aula,
        s.cupo_maximo,
        COALESCE(CONCAT(d.nombres, ' ', d.apellidos), 'SIN DOCENTE') AS docente,
        d.especialidad,
        COUNT(DISTINCT dm.id_detalle_matricula) AS total_alumnos_matriculados,
        CASE 
            WHEN COUNT(DISTINCT dm.id_detalle_matricula) = 0 THEN 'SIN ALUMNOS'
            ELSE 'CON ALUMNOS'
        END AS estado_seccion
    FROM seccion s
    INNER JOIN curso c 
        ON s.id_curso = c.id_curso
    INNER JOIN periodo_academico pa 
        ON s.id_periodo = pa.id_periodo
    LEFT JOIN docente d 
        ON s.id_docente = d.id_docente
    LEFT JOIN detalle_matricula dm 
        ON s.id_seccion = dm.id_seccion
    LEFT JOIN matricula m 
        ON dm.id_matricula = m.id_matricula
        AND m.estado <> 'ANULADA'
    WHERE (p_id_periodo IS NULL OR s.id_periodo = p_id_periodo)
    GROUP BY 
        pa.nombre,
        s.id_seccion,
        s.codigo_seccion,
        c.codigo,
        c.nombre,
        s.aula,
        s.cupo_maximo,
        d.nombres,
        d.apellidos,
        d.especialidad
    ORDER BY 
        total_alumnos_matriculados ASC,
        pa.nombre DESC,
        c.nombre ASC,
        s.codigo_seccion ASC;
END ;;
DELIMITER ;
